/bin/bash -c "python - <<'PY'
import cv2, numpy as np
z=np.load('source_pixels.npz')['rgb']
for i in range(96):
 im=z[i]; hsv=cv2.cvtColor(im,cv2.COLOR_RGB2HSV)
 out=[]
 for name,m in [('red',((hsv[:,:,0]<10)|(hsv[:,:,0]>170))&(hsv[:,:,1]>150)&(hsv[:,:,2]>100)),('blue',(hsv[:,:,0]>95)&(hsv[:,:,0]<125)&(hsv[:,:,1]>120)&(hsv[:,:,2]>60))]:
  m=m.astype('uint8'); n,l,stats,cents=cv2.connectedComponentsWithStats(m)
  best=[]
  for j in range(1,n):
   x,y,w,h,a=stats[j]
   if name=='red' and 95<x<130 and 45<y<65 and a>=3: best.append((a,round(cents[j][0],2),round(cents[j][1],2),w,h))
   if name=='blue' and 130<x<190 and 40<y<80 and a>=3: best.append((a,round(cents[j][0],2),round(cents[j][1],2),w,h))
  out.append(name+str(sorted(best,reverse=True)[:2]))
 print(f'{i:02d}',*out)
PY"
